// Read-only character sheet. All derived values use the same live loadout
// functions as combat; conditional talents remain listed separately.
function characterStats(){
 let rawCrit=5+stat('crit'),rawGuard=stat('guard'),speed=1+Math.min(.8,stat('speed')/100);
 return {hp:Math.max(0,p.hp),maxHP:maxhp(),mp:Math.max(0,p.mp),maxMP:100,attack:damage(),crit:Math.max(0,Math.min(60,rawCrit)),rawCrit,critMultiplier:1.65,guard:Math.min(65,rawGuard),rawGuard,armorFlat:(p.armor?.value||0)*.12,speed:205*speed,speedPercent:speed*100,manaRegen:7+p.focus*2+stat('regen'),lifeRegen:hasKey('ember')?maxhp()*.02:0,flask:maxhp()*.6*(hasKey('ember')?.5:1),spellScale:1.3+p.focus*.15+stat('spell')/100};
}
const csNumber=n=>Number.isFinite(n)?Number(n.toFixed(2)).toLocaleString('ja-JP'):'—';
const csRow=(label,value)=>'<div class="character-stat-row"><dt>'+gearEscape(label)+'</dt><dd>'+gearEscape(value)+'</dd></div>';
function characterSummaryHtml(){let s=characterStats();return '<section class="character-summary" aria-label="現在のステータス"><div class="character-summary-heading"><strong>自分のステータス <small>Lv '+p.level+'</small></strong><button id="characterStatsButton" onclick="showCharacterStats()">詳細ステータス</button></div><dl>'+csRow('HP',csNumber(s.hp)+' / '+csNumber(s.maxHP))+csRow('MP',csNumber(s.mp)+' / 100')+csRow('攻撃力',csNumber(s.attack))+csRow('会心率',csNumber(s.crit)+'%')+csRow('会心ダメ',csNumber(s.critMultiplier*100)+'％')+csRow('ダメージ軽減',csNumber(typeof totalClassGuard==='function'?totalClassGuard(s.guard):s.guard)+'%')+'</dl></section>';}
const characterPanelBase=panel;panel=kind=>{let result=characterPanelBase(kind);if(kind==='inventory'&&started&&!dead){let list=$('card').querySelector('.inventory-list');if(list&&!$('characterStatsButton'))list.insertAdjacentHTML('afterbegin',characterSummaryHtml())}return result};
let characterStatsTab='combat',characterStatsReturnIndex=0;
function characterCombatHtml(){let s=characterStats();return '<div class="character-stat-columns"><section><h3>攻撃</h3><dl>'+csRow('通常攻撃・基準威力',csNumber(s.attack))+csRow('通常攻撃のダメージ幅',csNumber(Math.round(s.attack*.85))+'〜'+csNumber(Math.round(s.attack*1.15))+'（会心・条件効果を除く）')+csRow('会心率',csNumber(s.crit)+'% / 上限60%')+csRow('会心率・上限適用前',csNumber(s.rawCrit)+'%')+csRow('会心ダメ',csNumber(s.critMultiplier*100)+'％')+csRow('魔法スキル・基礎倍率',csNumber(s.spellScale)+'倍')+csRow('移動速度',csNumber(s.speedPercent)+'% / '+csNumber(s.speed)+'距離/秒')+'</dl></section><section><h3>生存・回復</h3><dl>'+csRow('HP',csNumber(s.hp)+' / '+csNumber(s.maxHP))+csRow('MP',csNumber(s.mp)+' / 100')+csRow('割合軽減',csNumber(s.guard)+'% / 上限65%')+csRow('割合軽減・上限適用前',csNumber(s.rawGuard)+'%')+csRow('胴防具の固定軽減',csNumber(s.armorFlat)+' / 被弾')+csRow('自然マナ回復',csNumber(s.manaRegen)+' / 秒')+csRow('常時ライフ回復',csNumber(s.lifeRegen)+' / 秒')+csRow('生命瓶の回復量',csNumber(s.flask)+' / 本（最大HPまで）')+csRow('生命瓶の所持',p.flasks+' / 3')+'</dl></section></div><p class="muted">威力は敵の状態・距離・移動・星の加護などで変動します。条件付き効果は「星図・セット」に表示。継続ダメージと元素反応は会心しません。</p>';}
function characterBreakdownHtml(){let keys=['attack','life','spell','crit','speed','guard','regen'];let table='<div class="character-table-scroll"><table class="character-table"><thead><tr><th>補正</th><th>装備</th><th>小ノード</th><th>セット</th><th>誓約等</th><th>合計</th></tr></thead><tbody>'+keys.map(key=>{let equipment=affix(key),nodes=passive(key),sets=tagStat(key),total=stat(key);return '<tr><th>'+gearEscape(MODS[key]?.[0]||key)+'</th>'+[equipment,nodes,sets,total-equipment-nodes-sets,total].map(n=>'<td>'+csNumber(n)+'</td>').join('')+'</tr>'}).join('')+'</tbody></table></div>';
 return '<h3>補正の内訳</h3>'+table+'<p class="muted">この表は加算補正です。最大HP・攻撃力には、下記の基礎値と誓約の倍率も適用されます。条件付きの大ノードは別表示です。</p><div class="character-stat-columns"><section><h3>最大HPの計算</h3><dl>'+csRow('初期値','130')+csRow('レベル',csNumber(p.level*14))+csRow('生命力',csNumber(p.vitality*25))+csRow('胴防具',csNumber((p.armor?.value||0)*3))+csRow('ライフ補正',csNumber(stat('life')))+csRow('誓約の乗算',csNumber(keyLifeMultiplier())+'倍')+csRow('最終最大HP',csNumber(maxhp()))+'</dl></section><section><h3>攻撃力の計算</h3><dl>'+csRow('初期値','17')+csRow('レベル',csNumber(p.level*3))+csRow('力',csNumber(p.power*6))+csRow('武器の基礎値',csNumber(p.weapon?.value||0))+csRow('攻撃力補正',csNumber(stat('attack')))+csRow('誓約の乗算',csNumber(keyDamageMultiplier())+'倍')+csRow('最終攻撃力',csNumber(damage()))+'</dl></section></div>';}
function characterSkillsHtml(){return '<p class="muted">100%基準威力に各スキル固有の倍率・命中回数を適用します。表示はDPSや総ダメージではありません。</p><div class="character-skill-list">'+SKILL_ACTIONS.map((action,index)=>{let type=p.bindings[index],b=skillBuild(type);if(!b)return '<section><h3>枠 '+(index+1)+' · '+SKILL_KEYS[index]+'</h3><p>未装着／未割当</p></section>';let def=GEM[type],base=damage()*b.mult*(def.tags.includes('spell')?characterStats().spellScale:1.2);return '<section><h3>'+gearEscape(SKILL_KEYS[index]+' · '+gemDisplayName(b.gem))+'</h3><dl>'+csRow('ジェムレベル',b.gem.level)+csRow('100%基準威力',csNumber(base))+csRow('消費',skillCostLabel(b))+csRow('再使用時間',csNumber(b.cool)+'秒')+csRow('半径倍率',csNumber(b.radius)+'倍（範囲対応スキル）')+csRow('属性',(b.elements||[]).map(id=>ELEMENTS[id].name).join('・')||'なし')+csRow('リンク済みサポート',b.supports.map(t=>GEM[t].name).join('・')||'なし')+'</dl><p>'+gearEscape(def.desc)+'</p></section>'}).join('')+'</div>';}
function characterPassivesHtml(){let ownership=treeOwnership(),large=p.nodes.map(id=>NODES[id]).filter(n=>n?.key);return '<h3>取得済みの大きな星・誓約</h3><div class="character-effect-list">'+(large.length?large.map(n=>'<section><h4>'+gearEscape(n.name)+'</h4><p>'+gearEscape(n.key.desc)+'</p>'+(n.talent?'<small>'+ (ownership.complete.has(n.star)?'星の加護 発動中 · '+TREE_TALENTS[n.talent.branch][1](n.talent.tier*2):'加護未完成 · 周囲 '+TREE_STARS[n.star].members.filter(id=>ownership.owned.has(id)).length+' / '+TREE_STARS[n.star].members.length)+'</small>':'')+'</section>').join(''):'<p>まだ取得していません。</p>')+'</div><h3>装備タグ</h3><div class="character-effect-list">'+Object.entries(GEAR_TAGS).filter(([id])=>tagCount(id)>0).map(([id,tag])=>'<section><h4>'+tag.name+' · '+tagCount(id)+'部位</h4><p>'+ (tagStage(id)?tag.text.slice(0,tagStage(id)).join('<br>'):'2部位で最初の効果が発動')+'</p></section>').join('')+'</div>';}
function showCharacterStats(tab='combat'){
 if(!started||dead)return;
 if(menuSurface!=='character-stats')characterStatsReturnIndex=inventoryNav.index;
 if(!['combat','breakdown','skills','effects'].includes(tab))tab='combat';characterStatsTab=tab;
 let tabs=[['combat','攻撃・防御'],['breakdown','補正の内訳'],['skills','スキル'],['effects','星図・セット']];
 let content=tab==='combat'?characterCombatHtml():tab==='breakdown'?characterBreakdownHtml():tab==='skills'?characterSkillsHtml():characterPassivesHtml();
 worldMenu('詳細ステータス','<div class="character-stat-tabs">'+tabs.map(([id,name])=>'<button aria-pressed="'+(id===tab)+'" onclick="showCharacterStats(\''+id+'\')">'+name+'</button>').join('')+'</div><div class="character-stat-content">'+content+'</div>','character-stats');
 let close=$('card').querySelector('.close');close.textContent='装備へ戻る';close.setAttribute('onclick','returnFromCharacterStats()');
 let hint=$('card').querySelector('.panel-controls');if(hint)hint.textContent='十字キー：項目を選択 · A：決定 · B：装備へ戻る · 右スティック：スクロール';
}
function returnFromCharacterStats(){panel('inventory');inventoryNav.index=characterStatsReturnIndex;inventoryNav.actions=false;inventoryShowDetail();menuFocusElement($('characterStatsButton'));}
const characterCloseBase=closePanel;closePanel=(...args)=>{if(menuSurface==='character-stats')return returnFromCharacterStats();return characterCloseBase(...args)};
const characterPadBase=padMenu;padMenu=(g,left,right,dt)=>{if(menuSurface==='character-stats'&&padEdge(g,'back')){returnFromCharacterStats();return}return characterPadBase(g,left,right,dt)};
